/* Peach Media Cloud — self-contained interactive HTML/CSS/JS product prototype.
   Every screen runs on tenant-scoped demonstration data stored locally. */
(function(){'use strict';
const C=window.PeachCore;
const STORAGE_KEY='peach-media-demo-v2';
const UI_KEY='peach-media-ui-v2';
const groups=[
 {title:'工作空间',items:[['overview','总览工作台','◈'],['assets','数字资产','▧'],['projects','项目与环境','▣'],['folders','目录与集合','▤'],['metadata','元数据模板','☷'],['reviews','审核与版权','⚑'],['uploads','上传中心','⇧'],['storage','存储与文件','◉']]},
 {title:'计算与处理',items:[['jobs','处理任务','▣'],['workflows','任务工作流','◇'],['processors','处理器中心','⚙'],['runtimes','容器与 Worker','⬡'],['schedules','定时调度','◷']]},
 {title:'开放平台',items:[['api','API 与密钥','⌘'],['webhooks','Webhook 回调','↗'],['events','数据事件上报','⇵'],['delivery','媒体分发','◎']]},
 {title:'运营与安全',items:[['usage','数据分析','▥'],['billing','套餐与计费','◫'],['tenants','租户管理','▦'],['organizations','组织架构','♧'],['permissions','角色与权限','◇'],['monitor','系统监控','◴'],['audit','操作审计','≡'],['settings','系统设置','⚒']]}
];
const PAGE_META={overview:['工作台','全局工作负载与资产运营总览','WORKSPACE / OVERVIEW'],assets:['数字资产','统一管理图片、视频、音频、文档与数据资源','ASSET MANAGEMENT'],projects:['项目与环境','管理多项目和开发/生产环境边界','PROJECTS / ENVIRONMENTS'],metadata:['元数据模板','按企业自定义元数据 Schema 与字段','ASSET / METADATA'],reviews:['审核与版权','资产审核、发布及版权有效期控制','DAM / GOVERNANCE'],folders:['目录与集合','组织目录、虚拟集合与资产分类体系','LIBRARY / COLLECTIONS'],uploads:['上传中心','直传、分片、断点续传与安全入库','UPLOAD / INGEST'],storage:['存储与文件','多云对象存储、存储策略与生命周期','OBJECT STORAGE'],jobs:['处理任务','查看分布式处理任务的完整执行链路','PROCESSING / JOBS'],workflows:['任务工作流','编排扫描、转码、审核与发布流程','PROCESSING / WORKFLOWS'],processors:['处理器中心','Python、Go、FFmpeg 与自定义镜像管理','COMPUTE / REGISTRY'],runtimes:['容器与 Worker','Docker / Kubernetes 计算资源与隔离','COMPUTE / RUNTIMES'],schedules:['定时调度','周期任务、延时任务与工作流触发','SCHEDULER / FLOW'],api:['API 与密钥','开放接口、项目环境和访问凭证管理','DEVELOPER / OPEN API'],webhooks:['Webhook 回调','处理完成、资产发布和事件投递','DEVELOPER / WEBHOOKS'],events:['数据事件上报','第三方媒体访问与用量事件采集','INGEST / EVENTS'],delivery:['媒体分发','签名链接、CDN 与动态媒体变换','MEDIA / DELIVERY'],usage:['数据分析','存储、处理量、API 和分发用量','ANALYTICS / USAGE'],billing:['套餐与计费','租户资源配额、用量账本与计费基础','SAAS / BILLING'],tenants:['租户管理','企业租户生命周期与套餐配置','PLATFORM / TENANTS'],organizations:['组织架构','自定义组织类型与多层级组织管理','IDENTITY / ORGANIZATION'],permissions:['角色与权限','角色、数据范围、按钮和资源级授权','IDENTITY / AUTHORIZATION'],monitor:['系统监控','网关、RocketMQ、Worker 与业务状态','OPERATIONS / OBSERVABILITY'],audit:['操作审计','敏感操作与权限变更的可追溯记录','SECURITY / AUDIT'],settings:['系统设置','通用平台策略、资源治理和集成设置','PLATFORM / SETTINGS']};
let state,settings,route='overview',filter='all',query='',view='grid',modal=null,drawer=null,uploadProgress=[],toastTimer=null,intervals=[];
function persist(){try{localStorage.setItem(STORAGE_KEY,JSON.stringify(state));}catch(e){console.warn('Prototype cannot persist state',e);}}
function persistUI(){try{localStorage.setItem(UI_KEY,JSON.stringify(settings));}catch{}}
function init(){let stored=null;try{stored=JSON.parse(localStorage.getItem(STORAGE_KEY)||'null');}catch{}state=stored?.version===2?stored:C.createSeed();try{settings=JSON.parse(localStorage.getItem(UI_KEY)||'null')||{tenantId:'t1',dark:false};}catch{settings={tenantId:'t1',dark:false};}if(!state.tenants.some(t=>t.id===settings.tenantId))settings.tenantId='t1';route=(location.hash||'#overview').slice(1).split('?')[0];if(!PAGE_META[route])route='overview';render();bind();window.addEventListener('hashchange',()=>{const r=location.hash.slice(1).split('?')[0];if(PAGE_META[r]){route=r;filter='all';query='';drawer=null;modal=null;render();}});window.addEventListener('keydown',e=>{if(e.key==='Escape'){closeOverlay();}if((e.ctrlKey||e.metaKey)&&e.key==='k'){e.preventDefault();document.getElementById('global-search')?.focus();}});}
const esc=(s)=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const attr=esc;
const tenant=()=>settings.tenantId;
const scoped=(items)=>C.onlyTenant(items,tenant());
const fmt=(n)=>Number(n||0).toLocaleString('zh-CN');
const day=(d)=>{const x=new Date(d);return Number.isNaN(+x)?'—':x.toLocaleDateString('zh-CN',{month:'2-digit',day:'2-digit'});};
const when=(d)=>{const x=new Date(d);return Number.isNaN(+x)?'—':x.toLocaleString('zh-CN',{month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit'});};
const statusText={READY:'已就绪',PROCESSING:'处理中',QUARANTINED:'隔离扫描',DELETING:'清理中',QUEUED:'排队中',RUNNING:'执行中',SUCCEEDED:'已完成',FAILED:'失败',CANCELLED:'已取消',ACTIVE:'已启用',PAUSED:'已暂停',IDLE:'空闲',RETRY:'重试中',ACCEPTED:'已接收'};
const statusClass={READY:'success',PROCESSING:'purple',QUARANTINED:'warning',DELETING:'warning',QUEUED:'info',RUNNING:'purple',SUCCEEDED:'success',FAILED:'danger',CANCELLED:'danger',ACTIVE:'success',PAUSED:'warning',IDLE:'info',RETRY:'warning',ACCEPTED:'success'};
const badge=(s)=>`<span class="badge ${statusClass[s]||'purple'}">${esc(statusText[s]||s)}</span>`;
const assetIcon=(t)=>({image:'🖼️',video:'▶️',audio:'🎧',document:'📄',archive:'🗃️',dataset:'▦'}[t]||'📁');
const btn=(label,action,id='',kind='')=>`<button type="button" class="btn ${kind}" data-action="${attr(action)}" ${id?`data-id="${attr(id)}"`:''}>${label}</button>`;
const navItem=(x)=>`<button type="button" class="nav-link ${route===x[0]?'active':''}" data-route="${x[0]}"><span class="nav-icon">${x[2]}</span><span>${x[1]}</span>${x[0]==='jobs'?'<span class="nav-flag">LIVE</span>':''}</button>`;
function shell(){const current=PAGE_META[route];return `<aside class="sidebar" aria-label="主要导航"><a class="brand" href="#overview"><span class="brand-mark">🍑</span><span><span class="brand-name">Peach Media</span><br><span class="brand-sub">CLOUD PLATFORM</span></span></a><nav class="nav-scroll">${groups.map(g=>`<div class="nav-group-label">${g.title}</div>${g.items.map(navItem).join('')}`).join('')}</nav><div class="sidebar-bottom"><div class="small" style="display:flex;justify-content:space-between"><span>企业版 · 演示配额</span><span>42%</span></div><div class="progress-mini"><span></span></div><small>本地交互原型 · 无真实云端调用</small></div></aside><section class="shell-main"><header class="topbar"><div class="top-left"><button class="icon-button mobile-menu" aria-label="打开导航" data-action="menu">☰</button><div class="breadcrumb"><span>Peach Media</span><span> / </span><strong>${esc(current[0])}</strong></div><span class="demo-ribbon"><b></b> DEMO DATA</span></div><div class="top-right"><label class="global-search"><span>⌕</span><input id="global-search" placeholder="搜索功能 / 资源 / 任务…" aria-label="全局搜索，快捷键 Ctrl K"></label><select id="tenant-selector" class="tenant-select" aria-label="当前演示租户">${state.tenants.map(t=>`<option value="${t.id}" ${t.id===tenant()?'selected':''}>${esc(t.name)}</option>`).join('')}</select><button class="icon-button" data-action="toggle-theme" title="切换明暗主题" aria-label="切换明暗主题">◐</button><button class="icon-button" data-route="audit" title="查看消息和审计" aria-label="查看消息和审计">♧</button><span class="avatar" title="演示管理员">PM</span></div></header><main id="main" class="content"><div class="page-header"><div><span class="eyebrow">${esc(current[2])}</span><h1>${esc(current[0])}</h1><p class="page-desc">${esc(current[1])}</p></div><div class="header-actions">${route==='overview'?btn('浏览资产','go-assets','',''):btn('导出演示数据','export','','')}${btn('＋ 创建处理任务','new-job','','primary')}</div></div>${renderPage()}</main></section>`;}
function render(){document.body.classList.toggle('theme-dark',!!settings.dark);document.title=`${PAGE_META[route][0]} · Peach Media`;document.getElementById('app').innerHTML=shell();renderOverlay();}
function go(to){if(!PAGE_META[to])return;filter='all';query='';modal=null;drawer=null;document.getElementById('app')?.classList.remove('menu-open');location.hash=to;route=to;render();}
function panel(title,body,action='',sub=''){return `<section class="card"><div class="card-head"><div><h3>${title}</h3>${sub?`<small>${sub}</small>`:''}</div>${action}</div>${body}</section>`;}
function statsCard(label,value,change,icon,tone){return `<div class="metric-card ${tone}"><span class="metric-label">${label}</span><span class="metric-symbol" aria-hidden="true">${icon}</span><div><div class="metric-value">${value}</div><div class="metric-trend">${change}</div></div></div>`;}
function table(columns,rows){return `<div class="table-wrap"><table class="data-table"><thead><tr>${columns.map(x=>`<th>${x}</th>`).join('')}</tr></thead><tbody>${rows.length?rows.map(c=>`<tr>${c.map(t=>`<td>${t}</td>`).join('')}</tr>`).join(''):`<tr><td colspan="${columns.length}"><div class="empty"><span class="e-icon">⌕</span><h3>没有匹配数据</h3><div>试试调整筛选条件或切换租户。</div></div></td></tr>`}</tbody></table></div>`;}
function chart(){const series=[[20,31,26,37,38,53,45,66,59,71],[13,20,28,23,31,41,35,48,49,56],[8,13,16,15,20,25,21,28,34,41]];const toPath=p=>p.map((v,i)=>`${i?'L':'M'}${35+i*62} ${179-v*1.95}`).join(' ');return `<svg class="chart-svg" viewBox="0 0 615 200" role="img" aria-label="最近十天任务提交、完成和失败趋势示意图"><defs><linearGradient id="chartArea" x1="0" y1="0" x2="0" y2="1"><stop offset="0%" stop-color="#8477f4" stop-opacity=".23"/><stop offset="100%" stop-color="#8477f4" stop-opacity="0"/></linearGradient></defs>${[30,80,130,180].map(y=>`<line x1="30" y1="${y}" x2="598" y2="${y}" stroke="#eef0f7"/><text x="2" y="${y+3}" class="axis">${Math.round((180-y)*100)}</text>`).join('')}<path d="${toPath(series[0])} L593 181 L35 181 Z" fill="url(#chartArea)"/>${series.map((s,i)=>`<path d="${toPath(s)}" stroke="${['#7767ee','#20b49b','#ffb38b'][i]}" stroke-width="${i===0?3:2}" fill="none" stroke-linecap="round"/>`).join('')}${series[0].map((v,i)=>`<circle cx="${35+i*62}" cy="${179-v*1.95}" r="2.6" fill="#7566e8"/>`).join('')}${[1,3,5,7,9].map(i=>`<text x="${35+i*62}" y="197" text-anchor="middle" class="axis">11/${String(i+1).padStart(2,'0')}</text>`).join('')}</svg>`;}
function activity(){return scoped(state.audit).slice(0,5).map(a=>`<div class="activity-item"><div class="activity-icon">◈</div><div style="flex:1"><div class="activity-title">${esc(a.actor)} · ${esc(a.action)}</div><div class="activity-time">${esc(a.target)} · ${when(a.createdAt)}</div></div><span class="badge ${a.result==='成功'?'success':'danger'}">${a.result}</span></div>`).join('')||'<div class="empty">暂无活动记录</div>';}
function jobRow(j){const a=C.requireOwned(state.assets,tenant(),j.assetId);return[`<span class="table-row-link" data-action="job-detail" data-id="${attr(j.id)}">${esc(j.id)}</span>`,`<b>${esc(j.type)}</b><div class="small muted">${esc(a?.name||'关联资源已删除')}</div>`,badge(j.status),`<div class="progress ${j.status==='SUCCEEDED'?'green':''}"><span style="width:${j.progress}%"></span></div><span class="micro muted">${j.progress}%</span>`,esc(j.runtime),when(j.createdAt),`<div class="action-row">${btn('详情','job-detail',j.id,'sm')}${j.status==='FAILED'?btn('重试','retry-job',j.id,'sm'):j.status==='RUNNING'||j.status==='QUEUED'?btn('取消','cancel-job',j.id,'sm danger'):''}</div>`];}
function dashboard(){const s=C.summarize(state.assets,state.jobs,tenant());const tasks=scoped(state.jobs);return `<div class="hero"><div><span class="eyebrow">WELCOME TO PEACH MEDIA</span><h2>让每个数字资产，创造更多价值 ✨</h2><p>从企业级资产治理到容器化处理与开放交付，让多租户媒体数据形成安全、可观测的全链路闭环。</p><div class="action-row" style="margin-top:15px">${btn('上传新资源 ↗','open-upload','','primary')}${btn('浏览计算资源','go-runtimes')}</div></div><div class="hero-art" aria-hidden="true">🎞️</div></div><div class="metric-row">${statsCard('资产总数',fmt(s.totalAssets),'↑ 12.6% 近 30 日','▧','purple')}${statsCard('处理中任务',fmt(s.activeJobs),'异步消息队列运行中','◇','blue')}${statsCard('资产存储量',C.bytes(s.totalBytes),'配额使用 42%','◉','green')}${statsCard('本月 API 调用',tenant()==='t1'?'8,423,210':'127,439','↑ 24.8% 较上月','⌘','peach')}</div><div class="grid-2 spaced">${panel('任务处理趋势',`${chart()}<div class="mini-legend"><span><b style="background:#7767ee"></b>提交</span><span><b style="background:#20b49b"></b>已完成</span><span><b style="background:#ffb38b"></b>失败重试</span></div>`,btn('全部任务','go-jobs','','sm'),'近 10 日任务量（演示数据）')}${panel('资产类型分布',`<div class="donut-shell"><div class="donut"><span>${fmt(s.totalAssets)}<small>当前租户资产</small></span></div><div class="legend-rows">${Object.entries(C.TYPES).slice(0,5).map((x,i)=>`<div><span><b style="background:${['#7060f0','#a98df8','#8cdaca','#ffd5b1','#dae1ff'][i]}"></b>${x[1]}</span><strong>${scoped(state.assets).filter(a=>a.type===x[0]).length}</strong></div>`).join('')}</div></div>`)}</div><div class="grid-2 spaced">${panel('最近处理任务',table(['任务 ID','处理资源','状态','进度','运行模式','创建时间','操作'],tasks.slice(0,5).map(jobRow)),btn('查看全部 →','go-jobs','','sm'))}${panel('资源与安全事件',`<div class="activity-list">${activity()}</div>`,btn('操作审计 →','go-audit','','sm'))}</div><div class="spaced">${panel('完整媒体处理数据闭环',`<div class="overview-rail">${[['⬆','数据接入','直传 / API'],['🛡','隔离扫描','校验 / ClamAV'],['▦','异步编排','RocketMQ / Outbox'],['⬡','容器计算','Python / Go / K8s'],['◈','资产发布','版本 / 权限'],['↗','开放交付','CDN / Webhook'],['▥','用量核算','配额 / 审计']].map(a=>`<div class="rail-step"><span class="r-icon">${a[0]}</span><b>${a[1]}</b><small>${a[2]}</small></div>`).join('')}</div>`,'','从接收到交付的全过程可观测、可恢复')}</div>`;}
function assetsPage(){let rows=scoped(state.assets).filter(a=>(filter==='all'||a.type===filter)&&(!query||`${a.name} ${a.project} ${a.tag} ${a.owner}`.toLowerCase().includes(query.toLowerCase())));return `<div class="toolbar"><div class="toolbar-left"><input id="list-search" class="field search-input" placeholder="搜索文件名、标签或项目…" value="${attr(query)}" aria-label="搜索资产"><select id="asset-type" class="filter-select" aria-label="资产类型筛选"><option value="all">所有类型</option>${Object.entries(C.TYPES).map(([k,v])=>`<option value="${k}" ${filter===k?'selected':''}>${v}</option>`).join('')}</select></div><div class="toolbar-right">${btn(view==='grid'?'≡ 列表视图':'▦ 网格视图','toggle-asset-view')} ${btn('新建目录','new-folder')} ${btn('＋ 上传资产','open-upload','','primary')}</div></div><div class="info-banner">◈ 所有资源均按当前租户过滤。以下为本地演示数据；“处理”“分享”“删除”等操作只修改本浏览器的模拟状态。</div>${view==='grid'?`<div class="asset-grid">${rows.map(a=>`<article class="card asset-card" tabindex="0" role="button" aria-label="查看 ${attr(a.name)} 详情" data-action="asset-detail" data-id="${attr(a.id)}"><div class="asset-preview variant${a.variant}"><span class="asset-glyph">${assetIcon(a.type)}</span><span class="chip">${esc(C.TYPES[a.type])} · v${a.version}</span></div><div class="asset-body"><div class="asset-title" title="${attr(a.name)}">${esc(a.name)}</div><div class="asset-meta"><span>${esc(a.project)}</span><span>${C.bytes(a.size)}</span></div><div class="asset-meta">${badge(a.status)}<span>${day(a.createdAt)}</span></div></div></article>`).join('')||'<div class="empty">暂无匹配资源</div>'}</div>`:table(['资源','项目','类型','存储大小','状态','负责人','操作'],rows.map(a=>[`<span class="table-row-link" data-action="asset-detail" data-id="${a.id}">${esc(a.name)}</span>`,esc(a.project),esc(C.TYPES[a.type]),C.bytes(a.size),badge(a.status),esc(a.owner),btn('详情','asset-detail',a.id,'sm')]))}`;}
function foldersPage(){return `<div class="toolbar"><div class="toolbar-left"><div class="tabs"><button class="tab ${filter!=='collections'?'active':''}" data-action="folder-tab" data-id="folders">文件夹</button><button class="tab ${filter==='collections'?'active':''}" data-action="folder-tab" data-id="collections">虚拟集合</button></div></div><div class="toolbar-right">${btn('＋ 新建'+(filter==='collections'?'集合':'文件夹'),filter==='collections'?'new-collection':'new-folder','','primary')}</div></div><div class="grid-3">${(filter==='collections'?scoped(state.collections):scoped(state.folders)).map(x=>`<div class="card"><div style="font-size:31px;margin-bottom:11px">${filter==='collections'?'🗂️':'📁'}</div><strong>${esc(x.name)}</strong><div class="small muted">${filter==='collections'?'资产集合':'逻辑目录'} · ${x.count??x.assets} 个资产</div><div class="separator"></div>${btn('查看资产','go-assets','','sm')}${btn('重命名','rename-item',x.id,'sm')}</div>`).join('')||'<div class="empty">暂无目录/集合，可点击新建。</div>'}</div>`;}
function projectsPage(){return `<div class="toolbar"><div class="toolbar-left"><span class="small muted">项目是 API Key、资产、权限和用量的二级隔离与管理单元</span></div><div class="toolbar-right">${btn('＋ 新建项目','new-project','','primary')}</div></div><div class="grid-3">${scoped(state.projects).map(p=>`<div class="card"><div class="worker-title"><span class="worker-icon">▣</span><span class="badge info">${esc(p.env)}</span></div><h3>${esc(p.name)}</h3><div class="small muted">项目 ID：${esc(p.id)}</div><div class="separator"></div><div class="mini-stat-grid"><div class="mini-stat"><strong>${scoped(state.assets).filter(a=>a.project===p.name).length}</strong><small>演示资产</small></div><div class="mini-stat"><strong>${scoped(state.apiKeys).filter(k=>k.project===p.name).length}</strong><small>API Key</small></div><div class="mini-stat"><strong>${p.env==='Production'?'PROD':'DEV'}</strong><small>环境</small></div></div><div class="action-row spaced">${btn('查看资产','go-assets','','sm')}${btn('编辑环境','edit-project',p.id,'sm')}</div></div>`).join('')||'<div class="empty">暂无项目</div>'}</div>`;}
function metadataPage(){const rows=scoped(state.metadataSchemas||[]);return `<div class="toolbar"><div class="toolbar-left"><span class="small muted">自定义字段 Schema、字段类型、校验、索引、版本与资产分类体系</span></div><div class="toolbar-right">${btn('＋ 新建 Schema','new-schema','','primary')}</div></div>${panel('元数据模型',table(['Schema 名称','字段定义','状态','操作'],rows.map(x=>[esc(x.name),esc(x.fields),badge(x.status),`${btn('查看字段','schema-detail',x.id,'sm')}${btn(x.status==='ACTIVE'?'暂停':'恢复','toggle-schema',x.id,'sm')}`])))}<div class="grid-half spaced">${panel('元数据字段类型',`<div class="pill-row">${['String','Number','Boolean','Enum','DateTime','Reference','JSON','GeoPoint'].map(x=>`<span class="mini-pill">${x}</span>`).join('')}</div><p class="small muted spaced">不同租户可拥有不同字段类型、必填规则和索引策略；Schema 升级应可追溯历史版本。</p>`)}${panel('资产元数据示例',`<pre class="code-sample">{\n  "assetId": "ast_103",\n  "schema": "电商商品素材",\n  "metadata": {\n    "SKU": "SKU-1024",\n    "品牌": "Peach Demo",\n    "渠道": "官网商城"\n  }\n}</pre>`)}</div>`;}
function reviewsPage(){const rows=scoped(state.assets);return `<div class="toolbar"><div class="toolbar-left"><span class="small muted">审核发布与版权治理；原型通过演示状态驱动完整审核流程</span></div><div class="toolbar-right">${btn('查看全部资产','go-assets','','primary')}</div></div>${panel('待审与资产发布',table(['资产','类型','审核状态','版权/许可','操作'],rows.slice(0,12).map(a=>[esc(a.name),esc(C.TYPES[a.type]),`<span class="badge ${a.reviewStatus==='APPROVED'?'success':a.reviewStatus==='REJECTED'?'danger':'warning'}">${a.reviewStatus==='APPROVED'?'审核通过':a.reviewStatus==='REJECTED'?'已驳回':'待审核'}</span>`,esc(a.tag),`${btn('通过','approve-asset',a.id,'sm primary')}${btn('驳回','reject-asset',a.id,'sm danger')}${btn('查看','asset-detail',a.id,'sm')}`])))}<div class="grid-half spaced">${panel('审核发布流程',`<div class="flow-nodes"><div class="flow-node">草稿</div><span class="flow-arrow">→</span><div class="flow-node">待审</div><span class="flow-arrow">→</span><div class="flow-node">通过/驳回</div><span class="flow-arrow">→</span><div class="flow-node">发布/下架</div></div>`)}${panel('版权治理',`<p class="small muted">正式系统支持版权持有人、授权渠道、授权有效期、内容水印、审核记录与到期后的自动下架。原型显示标签和审核状态以便评审交互。</p>`)}</div>`;}
function uploadsPage(){return `${panel('上传文件到数字资产中心',`<div class="dropzone" id="dropzone" role="button" tabindex="0" aria-label="选择或拖放文件上传"><span class="big">☁️</span><strong>拖放文件至此处，或点击选择文件</strong><small>演示模式：仅模拟上传进度和文件记录，不向服务器传输二进制内容。</small><input class="file-input" id="native-file" type="file" multiple></div><div class="form-grid spaced"><label class="form-field">目标项目<select id="upload-project">${scoped(state.projects).map(p=>`<option value="${attr(p.name)}">${esc(p.name)}</option>`).join('')}</select></label><label class="form-field">上传策略<select><option>分片直传 · 自动判断</option><option>普通上传</option><option>模拟断点续传</option></select></label></div><div class="spaced" id="upload-progress">${uploadProgressMarkup()}</div>`,btn('查看上传架构','show-upload-flow','','sm'))}<div class="grid-half spaced">${panel('上传方式',`<div class="stack">${[['◉','对象存储直传','预签名 URL，不经过业务 Gateway 传输大文件'],['▦','分片与断点续传','按分片重试，支持网络中断恢复的后端方案'],['🛡','隔离与安全扫描','文件 MIME 校验、ClamAV 扫描、状态驱动发布'],['◇','处理流水线','上传完成自动触发元数据提取与媒体处理']].map(x=>`<div class="custom-list-item"><span class="icon">${x[0]}</span><div class="data"><strong>${x[1]}</strong><small>${x[2]}</small></div></div>`).join('')}</div>`)}${panel('最近上传资源',table(['文件名','大小','资产状态'],scoped(state.assets).slice(-6).reverse().map(a=>[esc(a.name),C.bytes(a.size),badge(a.status)])))}</div>`;}
function uploadProgressMarkup(){return uploadProgress.map(u=>`<div class="quota-row"><div><span><strong>${esc(u.name)}</strong> <span class="small muted">${C.bytes(u.size)}</span></span><span>${u.progress}% ${u.status==='DONE'?'· 完成':''}</span></div><div class="progress ${u.status==='DONE'?'green':''}"><span style="width:${u.progress}%"></span></div></div>`).join('')||'<div class="notice">选择本地文件后将出现进度模拟。刷新页面不会保存实际文件内容。</div>';}
function storagePage(){return `<div class="metric-row">${statsCard('总存储容量','50 TB','演示套餐上限','◉','blue')}${statsCard('已用容量',C.bytes(C.summarize(state.assets,state.jobs,tenant()).totalBytes),'基于本地演示资源统计','▤','green')}${statsCard('存储提供商','4','已设计适配：MinIO / S3 / OSS / R2','☁','purple')}${statsCard('待安全扫描',fmt(scoped(state.assets).filter(a=>a.status==='QUARANTINED').length),'隔离资产不可公开访问','🛡','peach')}</div><div class="grid-half spaced">${panel('对象存储连接',`<div class="stack">${[['MinIO 本地对象存储','主存储','ACTIVE'],['Amazon S3','云厂商扩展','PAUSED'],['阿里云 OSS','适配器预留','PAUSED'],['Cloudflare R2','S3 兼容适配','PAUSED']].map(x=>`<div class="custom-list-item"><span class="icon">☁</span><div class="data"><strong>${x[0]}</strong><small>${x[1]}</small></div>${badge(x[2])}</div>`).join('')}</div>`,btn('配置存储','configure-storage','','sm'))}${panel('文件生命周期',`<div class="stack">${[['QUARANTINED','上传完成后进入隔离区'],['PROCESSING','检查并生成衍生资源'],['READY','通过校验后正式发布'],['DELETING','异步清理对象与 CDN 缓存']].map(a=>`<div class="custom-list-item"><span class="data"><strong>${a[0]}</strong><small>${a[1]}</small></span></div>`).join('')}</div><div class="notice spaced">推荐隔离区 → 扫描 → 发布；删除采用 Saga + 对账修复。</div>`)}</div>`;}
function jobsPage(){const list=scoped(state.jobs).filter(j=>(filter==='all'||j.status===filter)&&(!query||`${j.id} ${j.type} ${j.processor}`.toLowerCase().includes(query.toLowerCase())));return `<div class="toolbar"><div class="toolbar-left"><input id="list-search" class="field search-input" value="${attr(query)}" placeholder="搜索任务 ID 或处理器…" aria-label="搜索任务"><select id="status-filter" class="filter-select" aria-label="状态筛选"><option value="all">全部状态</option>${C.TASK_STATES.map(v=>`<option value="${v}" ${filter===v?'selected':''}>${esc(statusText[v])}</option>`).join('')}</select></div><div class="toolbar-right">${btn('模拟任务推进','simulate-jobs')}${btn('＋ 新建任务','new-job','','primary')}</div></div><div class="metric-row">${statsCard('队列中',scoped(state.jobs).filter(j=>j.status==='QUEUED').length,'等待资源调度','◇','blue')}${statsCard('执行中',scoped(state.jobs).filter(j=>j.status==='RUNNING').length,'容器心跳正常（模拟）','⬡','purple')}${statsCard('成功',scoped(state.jobs).filter(j=>j.status==='SUCCEEDED').length,'处理产物已登记','✔','green')}${statsCard('失败',scoped(state.jobs).filter(j=>j.status==='FAILED').length,'支持重试与人工介入','!','peach')}</div><div class="card spaced">${table(['任务 ID','处理资源','状态','进度','运行模式','提交时间','操作'],list.map(jobRow))}</div><div class="grid-half spaced">${panel('执行状态模型',`<div class="flow-nodes"><div class="flow-node">CREATED</div><span class="flow-arrow">→</span><div class="flow-node">QUEUED</div><span class="flow-arrow">→</span><div class="flow-node">RUNNING</div><span class="flow-arrow">→</span><div class="flow-node">SUCCEEDED</div></div><p class="small muted spaced">失败进入 FAILED；可创建新 Attempt 重试；运行中的任务可 CANCEL。任务状态和容器状态分别持久化。</p>`)}${panel('处理执行闭环',`<div class="stack">${[['01','Outbox 可靠发布任务事件'],['02','队列削峰与租户公平调度'],['03','申请 Worker 资源和运行时租约'],['04','获取对象存储中的输入文件'],['05','生成 Output Manifest 并校验'],['06','发布资产并触发 Webhook 回调']].map(x=>`<div class="custom-list-item"><span class="badge purple">${x[0]}</span><span class="small">${x[1]}</span></div>`).join('')}</div>`)}</div>`;}
function workflowsPage(){return `<div class="toolbar"><div class="toolbar-left"><span class="small muted">按项目与租户隔离的可重试媒体处理流水线</span></div><div class="toolbar-right">${btn('＋ 新建工作流','new-pipeline','','primary')}</div></div><div class="grid-half">${scoped(state.pipelines).map(p=>`<div class="card"><div class="card-head"><div><h3>${esc(p.name)}</h3><small>${esc(p.trigger)}</small></div>${badge(p.enabled?'ACTIVE':'PAUSED')}</div><div class="flow-nodes">${p.steps.map((s,i)=>`${i?'<span class="flow-arrow">→</span>':''}<span class="flow-node">${esc(s)}</span>`).join('')}</div><div class="separator"></div><div class="action-row">${btn('立即运行','run-pipeline',p.id,'sm primary')}${btn(p.enabled?'停用':'启用','toggle-pipeline',p.id,'sm')}${btn('查看配置','pipeline-detail',p.id,'sm')}</div></div>`).join('')||'<div class="empty">尚无工作流</div>'}</div><div class="spaced">${panel('调度职责分工',`<div class="grid-3"><div class="outline-card"><b>OTRYX Flow</b><div class="small muted">计划触发、DAG、依赖与周期调度</div></div><div class="outline-card"><b>RocketMQ</b><div class="small muted">任务事件、队列削峰、重试与死信</div></div><div class="outline-card"><b>Peach Compute</b><div class="small muted">计算资源配额、Runtime 选择、Worker 租约</div></div></div>`)}</div>`;}
const processors=[['FFmpeg Transcoder','VIDEO_TRANSCODE','ffmpeg-worker:7.1','视频转码 / HLS / 截图','Kubernetes Job','4 CPU · 8 GiB'],['Image Vips','IMAGE_RESIZE','vips-worker:1.0','裁剪 / 压缩 / WebP','Worker Pool','1 CPU · 2 GiB'],['Python Vision','OCR_ANALYZE','python-worker:3.12','OCR / 图像分析 / 数据清洗','Kubernetes Job','2 CPU · 4 GiB'],['Go Archive','ARCHIVE_EXTRACT','go-worker:1.24','高并发校验 / 解压 / 文件拆分','Docker Job','2 CPU · 2 GiB'],['Document Convert','DOCUMENT_PREVIEW','document-worker:1.0','Office / PDF 预览','Kubernetes Job','2 CPU · 4 GiB'],['Audio Processor','AUDIO_NORMALIZE','ffmpeg-audio:7.1','响度标准化 / 音轨提取','Worker Pool','1 CPU · 2 GiB']];
function processorsPage(){return `<div class="toolbar"><div class="toolbar-left"><span class="info-banner" style="margin:0">☑ 镜像及运行环境为方案示例，不代表已部署实际处理器。</span></div><div class="toolbar-right">${btn('注册处理器','new-processor','','primary')}</div></div><div class="grid-3">${[...processors,...scoped(state.extraProcessors||[]).map(p=>[p.code,p.code,p.image,'租户自定义处理器（演示）',p.mode,'待审核'])].map((p,i)=>`<div class="card"><div class="worker-title"><span class="worker-icon">${['🎬','🖼','🐍','⚡','📄','🎵'][i%6]}</span>${badge('ACTIVE')}</div><h3>${esc(p[0])}</h3><p class="small muted">${esc(p[3])}</p><div class="separator"></div><div class="kv"><span class="label">处理器编码</span><b>${p[1]}</b></div><div class="kv"><span class="label">OCI 镜像</span><span>${p[2]}</span></div><div class="kv"><span class="label">默认运行时</span><span>${p[4]}</span></div><div class="kv"><span class="label">资源请求</span><span>${p[5]}</span></div><div class="action-row spaced">${btn('创建测试任务','new-job','','sm primary')}${btn('执行协议','processor-spec',p[1],'sm')}</div></div>`).join('')}</div>`;}
function runtimesPage(){return `<div class="metric-row">${statsCard('计算节点',state.workers.length,'Docker / Kubernetes 演示集群','⬡','purple')}${statsCard('运行中',state.workers.filter(w=>w.status==='RUNNING').length,'执行器状态心跳','◆','green')}${statsCard('任务并发',state.workers.reduce((s,w)=>s+w.tasks,0),'租户级资源额度','▤','blue')}${statsCard('队列等待',scoped(state.jobs).filter(j=>j.status==='QUEUED').length,'支持自动扩缩容设计','⌛','peach')}</div><div class="toolbar spaced"><div class="toolbar-left"><div class="tabs"><button class="tab ${filter!=='Docker'?'active':''}" data-action="runtime-filter" data-id="all">全部 Runtime</button><button class="tab ${filter==='Docker'?'active':''}" data-action="runtime-filter" data-id="Docker">Docker</button><button class="tab ${filter==='Kubernetes'?'active':''}" data-action="runtime-filter" data-id="Kubernetes">Kubernetes</button></div></div><div class="toolbar-right">${btn('配置执行环境','runtime-config','','primary')}</div></div><div class="grid-3">${state.workers.filter(w=>filter==='all'||w.runtime===filter).map(w=>`<div class="worker-card"><div class="worker-title"><span class="worker-icon">${w.image==='ffmpeg'?'🎬':w.image==='python'?'🐍':w.image==='go'?'⚡':'⬡'}</span>${badge(w.status)}</div><h3>${esc(w.name)}</h3><div class="small muted">${esc(w.runtime)} · ${esc(w.image)}-worker</div><div class="separator"></div><div class="metric-inline"><div><strong>${w.cpu} C</strong><small>CPU 限额</small></div><div><strong>${w.memory} GiB</strong><small>内存限额</small></div><div><strong>${w.tasks}</strong><small>正在执行</small></div></div><div class="quota-row"><div><span>模拟 CPU 使用率</span><b>${w.usage}%</b></div><div class="progress"><span style="width:${w.usage}%"></span></div></div><div class="action-row">${btn('查看详情','worker-detail',w.id,'sm')}${btn(w.status==='RUNNING'?'模拟停用':'模拟启用','toggle-worker',w.id,'sm')}</div></div>`).join('')}</div><div class="spaced">${panel('容器执行模式',`<div class="grid-half"><div class="outline-card"><b>常驻 Worker Pool</b><p class="small muted">适合高频图片处理、轻量校验、数据清洗。根据队列深度扩缩容。</p></div><div class="outline-card"><b>独立 Docker / Kubernetes Job</b><p class="small muted">适合视频转码、大型文档和 Python/Go 数据作业。每次任务采用资源限制与独立 Attempt。</p></div></div>`)}</div>`;}
function schedulesPage(){return `<div class="toolbar"><div class="toolbar-left"><span class="small muted">OTRYX Flow 集成方案：周期触发、DAG、延迟任务与失败重试</span></div><div class="toolbar-right">${btn('创建调度任务','new-schedule','','primary')}</div></div>${panel('周期调度任务',table(['任务名','Cron 表达式','下次触发','最近执行','状态','操作'],scoped(state.schedules).map(s=>[esc(s.name),`<code>${esc(s.cron)}</code>`,esc(s.next),esc(s.last),badge(s.status),`${btn('立即运行','run-schedule',s.id,'sm primary')}${btn(s.status==='ACTIVE'?'暂停':'恢复','toggle-schedule',s.id,'sm')}`])))}<div class="grid-half spaced">${panel('调度任务状态',`<div class="flow-nodes"><span class="flow-node">计划</span><span class="flow-arrow">→</span><span class="flow-node">触发</span><span class="flow-arrow">→</span><span class="flow-node">任务创建</span><span class="flow-arrow">→</span><span class="flow-node">执行/补偿</span></div><div class="notice spaced">必须区分调度成功与业务处理成功；调度事件持久化，任务执行须具幂等性。</div>`)}${panel('典型周期任务',`<div class="stack">${['上传会话与未完成分片清理','过期分享链接撤销','存储孤儿对象对账','失败处理任务补偿','按日用量账本聚合','资产保留策略和版本清理'].map(x=>`<div class="custom-list-item"><span class="icon">◷</span><span class="small">${x}</span></div>`).join('')}</div>`)}</div>`;}
function apiPage(){const rows=scoped(state.apiKeys);const endpoints=[['POST','/openapi/v1/uploads','申请直传与分片上传会话'],['POST','/openapi/v1/assets','创建资产元信息'],['GET','/openapi/v1/assets/{id}','查询资产 / 版本 / 产物'],['POST','/openapi/v1/jobs','创建媒体处理任务'],['GET','/openapi/v1/jobs/{id}','查询任务状态与进度'],['POST','/openapi/v1/events:batch','批量上报媒体行为事件'],['POST','/openapi/v1/delivery/sign','签名分发 URL']];return `<div class="toolbar"><div class="toolbar-left"><div class="tabs"><button class="tab ${filter!=='reference'?'active':''}" data-action="api-tab" data-id="keys">API Keys</button><button class="tab ${filter==='reference'?'active':''}" data-action="api-tab" data-id="reference">接口目录</button></div></div><div class="toolbar-right">${btn('＋ 创建密钥','new-key','','primary')}</div></div>${filter==='reference'?panel('开放接口目录',table(['方法','路径','说明'],endpoints.map(x=>[`<span class="badge ${x[0]==='GET'?'info':'success'}">${x[0]}</span>`,`<code>${x[1]}</code>`,x[2]]))):panel('项目级 API 密钥',table(['名称','项目','密钥前缀','权限范围','API 调用','状态','操作'],rows.map(k=>[esc(k.name),esc(k.project),`<code>${esc(k.prefix)}</code>`,`<span class="small">${esc(k.scope)}</span>`,fmt(k.calls),badge(k.status),`${btn(k.status==='ACTIVE'?'停用':'启用','toggle-key',k.id,'sm')}${btn('查看','key-detail',k.id,'sm')}`])))}<div class="grid-half spaced">${panel('开发者接入方式',`<div class="stack">${['服务端 API Key 认证与 Scope','浏览器 Signed Upload Policy','项目 / 环境边界与独立限流','幂等请求头、统一错误码','Webhook 签名校验与重放保护'].map(x=>`<div class="custom-list-item"><span class="icon">⌘</span><span class="small">${x}</span></div>`).join('')}</div>`)}${panel('API 调用示例',`<pre class="code-sample">POST /openapi/v1/uploads\nAuthorization: Bearer &lt;api-key&gt;\nIdempotency-Key: request-001\nContent-Type: application/json\n\n{\n  "filename": "launch-film.mp4",\n  "projectId": "pr1",\n  "size": 1073741824\n}</pre>`,btn('复制示例','copy-api','','sm'))}</div>`;}
function webhooksPage(){return `<div class="toolbar"><div class="toolbar-left"><span class="small muted">创建接收端点并订阅事件，展示模拟投递与失败重试结果</span></div><div class="toolbar-right">${btn('＋ 新建回调端点','new-webhook','','primary')}</div></div>${panel('Webhook 端点',table(['名称','回调地址','订阅事件','成功','失败','状态','操作'],scoped(state.webhooks).map(w=>[esc(w.name),`<span title="${attr(w.url)}" class="small">${esc(w.url)}</span>`,esc(w.events),fmt(w.success),fmt(w.failed),badge(w.status),`${btn('测试投递','test-webhook',w.id,'sm primary')}${btn(w.status==='ACTIVE'?'暂停':'恢复','toggle-webhook',w.id,'sm')}`])))}<div class="grid-half spaced">${panel('可靠投递策略',`<div class="custom-list">${['事件持久化及投递日志','HMAC-SHA256 签名和时间戳','指数退避、最大尝试次数','失败队列、人工重放','去重 Event ID 和幂等建议'].map(x=>`<div class="custom-list-item"><span class="icon">↗</span><span class="small">${x}</span></div>`).join('')}</div>`)}${panel('示例事件负载',`<pre class="code-sample">{\n  "eventId": "evt_demo_001",\n  "eventType": "job.succeeded",\n  "tenantId": "${tenant()}",\n  "assetId": "ast_102",\n  "jobId": "job_10021",\n  "occurredAt": "2026-11-06T10:00:00Z"\n}</pre>`)}</div>`;}
function eventsPage(){return `<div class="toolbar"><div class="toolbar-left"><span class="small muted">API / SDK / Webhook 的事件流是用量统计、审计和运营分析的数据来源</span></div><div class="toolbar-right">${btn('模拟上报事件','new-event','','primary')}</div></div><div class="metric-row">${statsCard('今日事件','128,405','批量接收 + MQ 异步聚合','⇵','purple')}${statsCard('接收成功率','99.96%','示例业务指标','✔','green')}${statsCard('重复去重','834','Event ID 幂等','◈','blue')}${statsCard('消费积压','28','演示消息队列深度','⌛','peach')}</div><div class="card spaced">${table(['事件 ID','事件类型','关联资源','结果','上报时间'],scoped(state.events).map(e=>[esc(e.id),`<code>${esc(e.type)}</code>`,esc(e.resource),badge(e.status),when(e.createdAt)]))}</div><div class="spaced">${panel('事件接收链路',`<div class="overview-rail">${[['⌘','外部 SDK','API Key'],['⇵','批量校验','Schema / Scope'],['◈','RocketMQ','削峰 / 去重'],['▥','事件归档','租户维度'],['▣','统计聚合','用量账本'],['◴','数据看板','指标报表']].map(x=>`<div class="rail-step"><span class="r-icon">${x[0]}</span><b>${x[1]}</b><small>${x[2]}</small></div>`).join('')}</div>`)}</div>`;}
function deliveryPage(){return `<div class="grid-half">${panel('媒体交付策略',`<div class="stack">${[['公共媒体','CDN 缓存 + 缩略图 + 格式协商','ACTIVE'],['签名私有媒体','有效期 / 项目 / 资源权限','ACTIVE'],['动态媒体转换','宽高 / 压缩 / 格式 / 水印','ACTIVE'],['跨域与防盗链','CORS / 域名白名单 / 引用源限制','ACTIVE']].map(x=>`<div class="custom-list-item"><span class="icon">◎</span><div class="data"><strong>${x[0]}</strong><small>${x[1]}</small></div>${badge(x[2])}</div>`).join('')}</div>`,btn('生成签名链接','sign-link','','sm primary'))}${panel('动态图片 URL 规则',`<pre class="code-sample">https://media.example.com/t/${tenant()}/\nasset_001/w_800,h_800,c_cover,f_webp,q_80</pre><div class="notice spaced">URL 仅用于展示设计规则。生产环境需要校验租户、原始资源权限、转换参数白名单和签名。</div>${btn('复制示例链接','copy-delivery','','sm')}`)}</div><div class="grid-half spaced">${panel('视频交付',`<div class="flow-nodes"><div class="flow-node">MP4 原视频</div><span class="flow-arrow">→</span><div class="flow-node">FFmpeg</div><span class="flow-arrow">→</span><div class="flow-node">多码率 HLS</div><span class="flow-arrow">→</span><div class="flow-node">CDN 缓存</div></div>`)}${panel('缓存与安全',`<div class="small">CDN Cache-Control、签名有效期、密钥轮换、失效通知、CDN Purge 与下载审计。</div><div class="action-row spaced">${btn('模拟刷新缓存','purge-cache','','sm')}${btn('查看分发用量','go-usage','','sm')}</div>`)}</div>`;}
function usagePage(){return `<div class="metric-row">${statsCard('本月 API 请求','8.42 M','较上月 +24.8%','⌘','purple')}${statsCard('CDN 分发流量','2.4 TB','全球流量计量（演示）','◎','blue')}${statsCard('视频转码分钟','14,280','按任务用量记录','🎬','green')}${statsCard('存储费用估算','¥ 2,480','仅供界面演示','¥','peach')}</div><div class="grid-2 spaced">${panel('日用量趋势',chart(),'','API / 转码 / 分发的模拟聚合趋势')}${panel('用量构成',`<div class="donut-shell"><div class="donut"><span>100%<small>当前租户</small></span></div><div class="legend-rows">${[['API 调用','44%','#7060f0'],['存储','22%','#a98df8'],['媒体处理','16%','#8cdaca'],['下行流量','10%','#ffd5b1'],['其他','8%','#dae1ff']].map(x=>`<div><span><b style="background:${x[2]}"></b>${x[0]}</span><strong>${x[1]}</strong></div>`).join('')}</div></div>`)}</div><div class="spaced">${panel('用量账本',table(['计量项目','单位','本月用量','核算方式','说明'],[['对象存储','GB·月','128.6','对象日快照','按租户 / 项目'],['媒体转码','分钟','14,280','处理结果记录','成功后结算'],['API 调用','次','8,423,210','有效请求账本','按 Key'],['CDN 下行','GB','2,458','交付日志聚合','按租户域名'],['文件安全扫描','次','6,862','扫描状态事件','任务完成后计量']].map(x=>x)))}</div>`;}
function billingPage(){const q=[['存储容量',6.5*1024,50*1024,'GB'],['月度 API 调用',8423210,15000000,'次'],['转码分钟数',14280,30000,'分钟'],['最大并发计算任务',scoped(state.jobs).filter(j=>j.status==='RUNNING').length,40,'个']];return `<div class="grid-half">${panel('当前 SaaS 套餐',`<div style="font-size:30px;font-weight:850">${esc(state.tenants.find(t=>t.id===tenant())?.plan||'Enterprise')}</div><p class="small muted">当前租户：${esc(state.tenants.find(t=>t.id===tenant())?.name)}</p><div class="separator"></div><div class="stack">${['租户级资源隔离','项目级 API 限流','工作负载公平调度','用量账本与配额预留','计费事件可审计'].map(x=>`<div class="check-row"><span style="color:var(--success)">✔</span>${x}</div>`).join('')}</div>`,btn('查看套餐配置','plan-detail','','sm'))}${panel('配额使用情况',q.map(x=>`<div class="quota-row"><div><span>${x[0]}</span><strong>${fmt(x[1])} / ${fmt(x[2])} ${x[3]}</strong></div><div class="progress"><span style="width:${C.percentage(x[1],x[2])}%"></span></div></div>`).join(''))}</div><div class="spaced">${panel('资源使用到费用核算',`<div class="flow-nodes"><span class="flow-node">额度预留</span><span class="flow-arrow">→</span><span class="flow-node">任务执行</span><span class="flow-arrow">→</span><span class="flow-node">用量凭证</span><span class="flow-arrow">→</span><span class="flow-node">计费账本</span><span class="flow-arrow">→</span><span class="flow-node">用量报表</span></div><p class="small muted spaced">重要：计费账本不能直接依赖 Redis 当前计数器；结算需具备可重放与审计事件。原型不提供真实支付或收费。</p>`)}</div>`;}
function tenantsPage(){return `<div class="toolbar"><div class="toolbar-left"><span class="small muted">平台管理员视角，演示租户生命周期与套餐边界</span></div><div class="toolbar-right">${btn('＋ 新建演示租户','new-tenant','','primary')}</div></div>${panel('租户列表',table(['租户名称','租户编码','套餐','成员数','状态','操作'],state.tenants.map(t=>[esc(t.name),`<code>${esc(t.code)}</code>`,esc(t.plan),fmt(t.users),badge(t.active?'ACTIVE':'PAUSED'),`${btn('切换到租户','switch-tenant',t.id,'sm primary')}${btn('套餐配置','tenant-detail',t.id,'sm')}`])))}<div class="grid-half spaced">${panel('租户隔离原则',`<div class="stack">${['tenant_id 是强制安全边界，不仅是查询条件','租户身份从可信认证上下文传递','Redis / MQ / 文件 / 任务 / 日志均附带租户上下文','跨租户管理员操作需明确平台身份与审计'].map(s=>`<div class="custom-list-item"><span class="icon">🛡</span><span class="small">${s}</span></div>`).join('')}</div>`)}${panel('租户资源模型',`<div class="flow-nodes"><div class="flow-node">Tenant</div><span class="flow-arrow">→</span><div class="flow-node">Organization</div><span class="flow-arrow">→</span><div class="flow-node">Project</div><span class="flow-arrow">→</span><div class="flow-node">Asset</div></div><p class="small muted spaced">一个集团可为单一租户，下属多个公司和项目；不强制一家公司对应一个租户。</p>`)}</div>`;}
function orgsPage(){const orgs=scoped(state.orgs);function depth(x){let d=0,p=x.parentId,seen=new Set();while(p&&d<10&&!seen.has(p)){seen.add(p);const parent=orgs.find(t=>t.id===p);if(!parent)break;d++;p=parent.parentId;}return d;}return `<div class="toolbar"><div class="toolbar-left"><span class="small muted">组织类型自定义，用户可兼属多个组织，角色绑定于组织作用域</span></div><div class="toolbar-right">${btn('＋ 新建组织单元','new-org','','primary')}${btn('管理成员','manage-members')}</div></div><div class="grid-2">${panel('当前租户组织树',`<div class="org-tree">${orgs.map(o=>`<div class="org-node" style="margin-left:${Math.min(depth(o),5)*19}px"><span><span class="nlabel">${depth(o)>0?'└─ ':''}${esc(o.name)}</span><span class="small muted" style="margin-left:12px">${esc(o.type)}</span></span>${btn('编辑','edit-org',o.id,'sm')}</div>`).join('')||'<div class="empty">尚未建立组织架构</div>'}</div>`)}${panel('组织关系成员',table(['姓名','所属组织','角色'],scoped(state.members).map(m=>[esc(m.name),esc(m.org),m.roles.map(esc).join(', ')])))}</div><div class="spaced">${panel('权限计算关系',`<div class="overview-rail">${[['◉','可信身份','用户 / 租户'],['♧','组织关系','主组织 / 兼属'],['◇','角色绑定','作用域 / 策略'],['▤','数据范围','部门 / 项目 / 资源'],['🛡','后端校验','API + 资源操作']].map(x=>`<div class="rail-step"><span class="r-icon">${x[0]}</span><b>${x[1]}</b><small>${x[2]}</small></div>`).join('')}</div>`)}</div>`;}
function permsPage(){return `<div class="toolbar"><div class="toolbar-left"><span class="small muted">菜单 / 按钮 / API / 字段 / 数据范围，统一授权策略</span></div><div class="toolbar-right">${btn('＋ 新建角色','new-role','','primary')}</div></div><div class="grid-half">${panel('角色权限矩阵',table(['角色','数据范围','资源授权','操作'],scoped(state.roles).map(r=>[esc(r.name),esc(r.scope),`<div class="pill-row">${r.permissions.slice(0,4).map(p=>`<span class="mini-pill">${esc(p)}</span>`).join('')}</div>`,btn('查看权限','role-detail',r.id,'sm')])))}${panel('按钮级权限示例',`<div class="stack">${[['asset:read','查看资产'],['asset:upload','上传资源'],['asset:publish','发布资源'],['job:create','创建处理任务'],['job:cancel','取消任务'],['key:create','创建 API Key'],['billing:read','查看用量账本']].map(x=>`<div class="custom-list-item"><span class="badge purple">${x[0]}</span><span class="small">${x[1]}</span></div>`).join('')}</div>`)} </div><div class="spaced">${panel('数据权限策略',`<div class="grid-3"><div class="outline-card"><strong>租户边界</strong><div class="small muted">tenant_id 强制隔离，禁止角色绕过</div></div><div class="outline-card"><strong>组织与项目范围</strong><div class="small muted">组织树、自定义组织、跨项目协作授权</div></div><div class="outline-card"><strong>资源及字段约束</strong><div class="small muted">资产、目录、分享、元数据字段级权限</div></div></div>`)}</div>`;}
function monitorPage(){return `<div class="metric-row">${statsCard('网关可用性','99.98%','示例监控指标','◈','green')}${statsCard('API P95','38 ms','控制面延迟（模拟）','⌘','blue')}${statsCard('MQ 消息积压','328','可观测的削峰队列（模拟）','◈','purple')}${statsCard('任务失败率','0.3%','7 日模拟均值','!','peach')}</div><div class="grid-2 spaced">${panel('服务健康状态',table(['服务','作用','状态','P95 延迟'],[['Peach Gateway','API 路由与限流','ACTIVE','38 ms'],['Peach Auth','权限与租户','ACTIVE','19 ms'],['Peach FileService','上传 / 存储','ACTIVE','82 ms'],['Peach Media Asset','资产元数据','ACTIVE','27 ms'],['Peach Media Compute','容器调度','ACTIVE','45 ms'],['RocketMQ','异步事件','ACTIVE','—']].map(x=>[esc(x[0]),esc(x[1]),badge(x[2]),esc(x[3])])))}${panel('消息与处理指标',`${chart()}<div class="mini-legend"><span><b style="background:#7767ee"></b>流入</span><span><b style="background:#20b49b"></b>成功消费</span><span><b style="background:#ffb38b"></b>重试</span></div>`)}</div><div class="grid-half spaced">${panel('可观测性组件',`<div class="stack">${['Prometheus / Grafana — 技术指标','SkyWalking — 链路追踪','Loki / Alloy — 日志采集','OpenTelemetry — Trace / Span 关联','业务事件审计 — actor / resource / tenant'].map(s=>`<div class="custom-list-item"><span class="icon">◴</span><span class="small">${s}</span></div>`).join('')}</div>`)}${panel('故障演练',`<div class="notice">点击模拟故障会新增一条审计记录，不会真的断开任何基础设施。</div><div class="action-row spaced">${btn('模拟 MQ 堆积','inject-mq','','sm')}${btn('模拟 Worker 宕机','inject-worker','','sm')}${btn('模拟重试任务','inject-retry','','sm')}</div>`)}</div>`;}
function auditPage(){return `<div class="toolbar"><div class="toolbar-left"><input id="list-search" class="field search-input" value="${attr(query)}" placeholder="搜索人员、行为、资源…" aria-label="搜索审计日志"></div><div class="toolbar-right">${btn('导出审计日志','export-audit','','primary')}</div></div>${panel('安全审计与业务日志',table(['记录 ID','操作人','操作动作','资源','结果','时间'],scoped(state.audit).filter(a=>!query||`${a.actor} ${a.action} ${a.target}`.toLowerCase().includes(query.toLowerCase())).map(a=>[esc(a.id),esc(a.actor),`<strong>${esc(a.action)}</strong>`,esc(a.target),`<span class="badge ${a.result==='成功'?'success':'danger'}">${esc(a.result)}</span>`,when(a.createdAt)])))}<div class="spaced info-banner">◈ 生产实现应保留授权失败、API Key 变更、租户切换、文件下载、资产删除、策略编辑、执行器操作等不可抵赖审计证据。</div>`;}
function settingsPage(){const entries=[['security','强制租户上下文校验','所有 HTTP、MQ、任务、缓存和文件操作都需带有可信租户上下文',true],['scan','文件入库前恶意文件扫描','未经安全扫描的资产不得公开交付',true],['outbox','可靠事件发布','任务与用量事件采用 Transactional Outbox',true],['quota','租户公平计算配额','并发、CPU、内存、临时盘和流量上限',true],['webhook','Webhook 签名与重放保护','外部回调使用 HMAC 签名、时间戳和 nonce',true],['preview','私有媒体预览保护','私有媒体使用短期授权访问',true]];return `<div class="grid-half">${panel('平台治理策略',`<div class="stack">${entries.map(e=>`<div class="custom-list-item"><div class="data"><strong>${e[1]}</strong><small>${e[2]}</small></div><input type="checkbox" class="toggle" data-action="toggle-setting" data-id="${e[0]}" ${settings[e[0]]!==false?'checked':''} aria-label="${esc(e[1])}"></div>`).join('')}</div>`, '', '开关仅变更原型本地状态，不会改变真实安全规则')}${panel('演示工作台',`<div class="stack">${[['配色主题',settings.dark?'深色模式':'浅色模式'],['当前租户',state.tenants.find(t=>t.id===tenant())?.name],['数据存储','浏览器 localStorage'],['原型类型','静态 HTML/CSS/JS'],['后端连接','无（纯演示）']].map(e=>`<div class="kv"><span class="label">${e[0]}</span><b>${esc(e[1])}</b></div>`).join('')}</div><div class="action-row spaced">${btn('切换主题','toggle-theme','','sm')}${btn('重置演示数据','reset','','sm danger')}</div>`)}</div><div class="spaced">${panel('原型边界',`<div class="notice">本交互原型提供导航、筛选、模拟增删改查、上传进度和任务状态流转，用于评审产品需求。它不具备真正认证鉴权、对象存储、转码执行、Docker/K8s 调度、支付结算、消息发送或外部数据上报能力。生产实现以仓库内 PRD 与架构文档为准。</div>`)}</div>`;}
function renderPage(){return ({overview:dashboard,assets:assetsPage,projects:projectsPage,metadata:metadataPage,reviews:reviewsPage,folders:foldersPage,uploads:uploadsPage,storage:storagePage,jobs:jobsPage,workflows:workflowsPage,processors:processorsPage,runtimes:runtimesPage,schedules:schedulesPage,api:apiPage,webhooks:webhooksPage,events:eventsPage,delivery:deliveryPage,usage:usagePage,billing:billingPage,tenants:tenantsPage,organizations:orgsPage,permissions:permsPage,monitor:monitorPage,audit:auditPage,settings:settingsPage})[route]();}
function kvRows(items){return items.map(x=>`<div class="kv"><span class="label">${esc(x[0])}</span><span>${x[1]}</span></div>`).join('');}
function openDrawer(kind,id){let title='',html='';if(kind==='asset'){const a=C.requireOwned(state.assets,tenant(),id);if(!a){notify('无权查看此租户之外的资产','err');return;}title='资产详情 · '+a.name;html=`<div class="drawer-visual">${assetIcon(a.type)}</div><div class="detail-stats"><div class="detail-stat"><span class="muted small">文件大小</span><b>${C.bytes(a.size)}</b></div><div class="detail-stat"><span class="muted small">当前状态</span><b>${badge(a.status)}</b></div></div>${kvRows([['资产 ID',esc(a.id)],['资产类型',esc(C.TYPES[a.type])],['所属项目',esc(a.project)],['负责人',esc(a.owner)],['资产标签',esc(a.tag)],['创建时间',when(a.createdAt)],['版本',String(a.version)],['租户边界',esc(a.tenantId)]])}<div class="action-row spaced">${btn('新建处理任务','create-job-asset',a.id,'primary')}${btn('编辑元数据','edit-asset',a.id)}${btn('分享','share-asset',a.id)}${btn('版本历史','versions-asset',a.id)}${btn('删除','delete-asset',a.id,'danger')}</div><div class="notice spaced">演示资源不包含真实二进制文件；生产系统应通过授权签名链接访问原件与衍生产物。</div>`;
}else if(kind==='job'){const j=C.requireOwned(state.jobs,tenant(),id);if(!j){notify('当前租户无法查看此任务','err');return;}title='处理任务 · '+j.id;html=`${kvRows([['状态',badge(j.status)],['处理类型',esc(j.type)],['资源 ID',esc(j.assetId)],['执行器',esc(j.processor)],['运行时',esc(j.runtime)],['Attempt',String(j.attempt)],['提交时间',when(j.createdAt)]])}<div class="spaced"><div class="card-head"><h3>执行进度</h3><span>${j.progress}%</span></div><div class="progress"><span style="width:${j.progress}%"></span></div></div><div class="separator"></div><h3>阶段记录</h3><div class="stack">${j.steps.map((s,i)=>`<div class="custom-list-item"><span class="badge ${i<=Math.floor(j.progress/17)?'success':'info'}">${i+1}</span><div class="data"><strong>${esc(s)}</strong><small>${i<=Math.floor(j.progress/17)?'模拟阶段已完成':'待处理'}</small></div></div>`).join('')}</div><div class="action-row spaced">${btn('推进模拟任务','simulate-job-one',j.id,'primary')}${j.status==='FAILED'?btn('重试','retry-job',j.id):j.status==='RUNNING'||j.status==='QUEUED'?btn('取消','cancel-job',j.id,'danger'):''}</div>`;
}else if(kind==='worker'){const w=state.workers.find(x=>x.id===id);if(!w)return;title='执行器详情 · '+w.name;html=`${kvRows([['Worker ID',w.id],['运行环境',esc(w.runtime)],['处理镜像',esc(w.image)],['CPU 限额',w.cpu+' Core'],['内存限额',w.memory+' GiB'],['执行状态',badge(w.status)],['并发任务数',String(w.tasks)],['CPU 使用率',w.usage+'%']])}<div class="separator"></div><h3>容器运行安全约束（设计要求）</h3><p class="small muted">非 root、只读根文件系统、CPU / 内存 / 临时盘配额、NetworkPolicy、禁止特权容器、最小 RBAC、镜像白名单和摘要校验。</p>`;
}else{const p=scoped(state.pipelines).find(x=>x.id===id);if(!p)return;title='工作流详情 · '+p.name;html=`${kvRows([['触发方式',esc(p.trigger)],['状态',badge(p.enabled?'ACTIVE':'PAUSED')],['步骤数',String(p.steps.length)]])}<div class="separator"></div><div class="stack">${p.steps.map((s,i)=>`<div class="custom-list-item"><span class="badge purple">${i+1}</span><strong>${esc(s)}</strong></div>`).join('')}</div>`;}
drawer={title,html};modal=null;renderOverlay();}
function field(label,name,value='',type='text',attrs=''){return `<label class="form-field"><span>${label}</span><input name="${attr(name)}" type="${attr(type)}" value="${attr(value)}" ${attrs}></label>`;}
function choice(label,name,options){return `<label class="form-field"><span>${label}</span><select name="${attr(name)}">${options.map(([v,l])=>`<option value="${attr(v)}">${esc(l)}</option>`).join('')}</select></label>`;}
function form(id,body){return `<form data-form="${id}" novalidate><div class="form-grid">${body}</div><div class="form-actions"><button type="button" class="btn" data-action="close">取消</button><button type="submit" class="btn primary">保存</button></div></form>`;}
function showModal(kind,id=''){let title='',html='',wide=false;switch(kind){
case 'new-project':title='创建项目';html=form('new-project',field('项目名称','name','','text','required')+choice('运行环境','env',[['Production','Production'],['Development','Development'],['Staging','Staging']]));break;
case 'new-schema':title='新增元数据 Schema';html=form('new-schema',field('Schema 名称','name','','text','required')+field('字段列表（逗号分隔）','fields','版权人,到期日期,使用范围','text','required'));break;
case 'edit-project':{const p=C.requireOwned(state.projects,tenant(),id);if(!p)return;title='编辑项目环境';html=form('edit-project',field('项目名称','name',p.name,'text','required')+choice('运行环境','env',[['Production','Production'],['Development','Development'],['Staging','Staging']])+`<input type="hidden" name="id" value="${attr(id)}">`);break;}
case 'schema-detail':{const s=C.requireOwned(state.metadataSchemas||[],tenant(),id);if(!s)return;title='元数据 Schema · '+s.name;html=kvRows([['Schema',esc(s.name)],['字段',esc(s.fields)],['状态',badge(s.status)]])+'<div class="notice spaced">字段约束与动态索引由后端 Schema 引擎实施；原型展示字段集合。</div>';break;}
case 'versions-asset':{const a=C.requireOwned(state.assets,tenant(),id);if(!a)return;title='资产版本历史 · '+a.name;html=`<div class="stack">${Array.from({length:a.version},(_,i)=>`<div class="custom-list-item"><span class="badge ${i===0?'success':'info'}">v${a.version-i}</span><div class="data"><strong>版本 ${a.version-i}</strong><small>${i===0?'当前版本':'历史版本 · 示例数据'}</small></div></div>`).join('')}</div><div class="form-actions">${btn('模拟回滚至上一版本','rollback-asset',a.id,'primary')}</div>`;break;}
case 'new-job':title='创建媒体处理任务';html=form('new-job',choice('选择资产','assetId',scoped(state.assets).map(a=>[a.id,a.name]))+choice('处理类型','type',[['IMAGE_RESIZE','图片压缩与尺寸'],['VIDEO_TRANSCODE','视频转码'],['VIDEO_HLS','HLS 打包'],['DOCUMENT_PREVIEW','文档预览'],['AUDIO_NORMALIZE','音频标准化'],['DATA_VALIDATE','数据处理校验']])+choice('执行环境','runtime',[['Auto','自动选择'],['Kubernetes Job','Kubernetes 独立 Job'],['Docker Job','Docker 独立容器'],['Worker Pool','常驻处理池']]));break;
case 'new-folder':title='新建逻辑目录';html=form('new-folder',field('目录名称','name','','text','required maxlength="70"'));break;
case 'new-collection':title='新建虚拟集合';html=form('new-collection',field('集合名称','name','','text','required maxlength="70"'));break;
case 'rename-item':{const item=[...state.folders,...state.collections].find(x=>x.id===id&&x.tenantId===tenant());if(!item)return;title='重命名';html=form('rename-item',field('名称','name',item.name,'text','required maxlength="70"')+`<input type="hidden" name="id" value="${attr(item.id)}">`);break;}
case 'edit-asset':{const a=C.requireOwned(state.assets,tenant(),id);if(!a)return;title='编辑资产元数据';html=form('edit-asset',field('文件显示名称','name',a.name,'text','required maxlength="180"')+field('标签','tag',a.tag,'text','maxlength="100"')+`<input type="hidden" name="id" value="${attr(id)}">`);break;}
case 'delete-asset':{const a=C.requireOwned(state.assets,tenant(),id);if(!a)return;title='确认删除资产';html=`<div class="info-banner" style="background:#fff1f1;color:#ad5060">这会删除本地演示资产记录及其关联任务。真实系统必须采用删除状态机、异步对象清理、引用检查和审计。</div><p><b>${esc(a.name)}</b></p><div class="form-actions">${btn('取消','close')}${btn('确认删除','confirm-delete',id,'danger')}</div>`;break;}
case 'new-key':title='创建 Open API 密钥';html=form('new-key',field('密钥名称','name','','text','required maxlength="70"')+choice('所属项目','project',scoped(state.projects).map(x=>[x.name,x.name]))+choice('权限范围','scope',[['assets:read','只读资产'],['assets:read,uploads:write','读取与上传'],['assets:read,job:create','读取与处理'],['assets:read,uploads:write,job:create','媒体读写']]))+'<p class="notice spaced">生产系统只存储密钥摘要；密钥明文应只在创建时显示一次。</p>';break;
case 'new-webhook':title='创建 Webhook 端点';html=form('new-webhook',field('端点名称','name','','text','required maxlength="80"')+field('回调 URL（HTTPS）','url','https://example.com/hooks/media','url','required')+choice('订阅事件','events',[['job.succeeded','job.succeeded'],['asset.ready','asset.ready'],['asset.published','asset.published'],['job.failed','job.failed']]));break;
case 'new-event':title='上报媒体事件（模拟）';html=form('new-event',choice('事件类型','type',[['asset.viewed','asset.viewed'],['asset.downloaded','asset.downloaded'],['asset.uploaded','asset.uploaded'],['job.succeeded','job.succeeded']])+choice('关联资产','resource',scoped(state.assets).map(a=>[a.id,a.name])));break;
case 'new-pipeline':title='新建工作流';html=form('new-pipeline',field('工作流名称','name','','text','required')+choice('触发条件','trigger',[['资产上传完成','上传完成'],['API 触发','开放 API'],['每日 02:00','每日 02:00']])+`<label class="form-field full">流水线步骤（用逗号分隔）<textarea name="steps" rows="3" required placeholder="安全扫描,元数据提取,视频转码,资产发布"></textarea></label>`);break;
case 'new-schedule':title='新增周期调度任务';html=form('new-schedule',field('任务名称','name','','text','required')+field('Cron 表达式','cron','0 0 2 * * ?','text','required'));break;
case 'new-tenant':title='创建演示租户';html=form('new-tenant',field('租户名称','name','','text','required')+field('租户编码','code','','text','required pattern="[A-Za-z][A-Za-z0-9_-]{2,31}"')+choice('套餐','plan',[['Basic','Basic'],['Professional','Professional'],['Enterprise','Enterprise']]));break;
case 'new-org':title='新增组织单元';html=form('new-org',field('组织名称','name','','text','required')+field('组织类型','type','部门','text','required')+choice('上级组织','parentId',[['','根组织'],...scoped(state.orgs).map(o=>[o.id,o.name])]));break;
case 'edit-org':{const o=C.requireOwned(state.orgs,tenant(),id);if(!o)return;title='编辑组织单元';html=form('edit-org',field('组织名称','name',o.name,'text','required')+field('组织类型','type',o.type,'text','required')+`<input type="hidden" name="id" value="${attr(o.id)}">`);break;}
case 'new-role':title='创建角色';html=form('new-role',field('角色名称','name','','text','required')+choice('数据范围','scope',[['本人数据','本人数据'],['本部门及下级','本部门及下级'],['指定资产库','指定资产库'],['全部租户资源','全部租户资源']])+field('权限编码（逗号分隔）','permissions','asset:read','text','required'));break;
case 'sign-link':title='生成模拟签名资源链接';html=form('sign-link',choice('选择资产','assetId',scoped(state.assets).map(a=>[a.id,a.name]))+choice('有效时长','duration',[['300','5 分钟'],['3600','1 小时'],['86400','24 小时']]));break;
case 'share-asset':title='分享演示资产';html=form('sign-link',`<input type="hidden" name="assetId" value="${attr(id)}">`+choice('有效时长','duration',[['3600','1 小时'],['86400','24 小时']]));break;
case 'processor-spec':title='Worker 执行协议 · '+id;html=`<div class="notice">Worker 获取 Job Manifest，按照限定资源执行，通过进度/心跳 API 报告状态，产物写入独立 Attempt 目录。仅对成功的 Attempt 提交 Output Manifest。</div><pre class="code-sample spaced">{\n  "jobId": "job_10021",\n  "attemptId": "attempt_001",\n  "processor": "${esc(id)}",\n  "tenantId": "${tenant()}",\n  "input": {"objectKey":"quarantine/input.mp4"},\n  "output": {"prefix":"processing/job_10021/attempt_001/"}\n}</pre>`;break;
case 'runtime-config':title='容器运行环境（规划）';html=`<div class="stack">${[['Docker Agent','开发 / 轻量部署，用最小权限管理 Engine API'],['Kubernetes Job','生产计算，采用 Namespace / ResourceQuota / Pod Security'],['KEDA / HPA','按队列积压和运行资源自动扩缩容'],['Processor Registry','按允许的镜像 Digest 与资源 Profile 调度']].map(x=>`<div class="custom-list-item"><span class="data"><strong>${x[0]}</strong><small>${x[1]}</small></span></div>`).join('')}</div><div class="notice spaced">这里只展示部署方案，不会创建任何容器。</div>`;break;
case 'new-processor':title='注册计算处理器（方案演示）';html=form('new-processor',field('处理器编码','code','','text','required')+field('OCI 镜像及版本','image','registry.example.com/media/custom:1.0','text','required')+choice('执行模式','mode',[['Kubernetes Job','Kubernetes Job'],['Worker Pool','常驻 Worker'],['Docker Job','Docker Job']]))+'<div class="notice spaced">演示中保存操作会显示说明，正式实现需进行镜像审核、Digest 锁定、安全扫描、资源配额和租户隔离。</div>';break;
case 'show-upload-flow':title='大文件上传全链路';html=`<div class="flow-nodes"><div class="flow-node">客户端</div><span class="flow-arrow">→</span><div class="flow-node">上传会话与签名</div><span class="flow-arrow">→</span><div class="flow-node">MinIO / S3 直传</div><span class="flow-arrow">→</span><div class="flow-node">隔离与扫描</div><span class="flow-arrow">→</span><div class="flow-node">资产发布</div></div><p class="small muted spaced">数据字节流不穿过业务 Gateway。分片清单持久化，过期会话由定时任务回收。</p>`;wide=true;break;
case 'plan-detail':title='套餐配额设计';html=`<div class="notice">建议先实现配额预留 / 结算 / 释放；计费账单需可审计的不可变用量凭据，后续再接支付。</div>${kvRows([['Basic','2 个并发任务 / 50 GB 存储'],['Professional','10 个并发任务 / 2 TB 存储'],['Enterprise','按合同配置资源池与存储策略']])}`;break;
case 'tenant-detail':{const t=state.tenants.find(x=>x.id===id);if(!t)return;title='租户配置 · '+t.name;html=kvRows([['租户编码',t.code],['套餐',t.plan],['成员数',String(t.users)],['状态',badge(t.active?'ACTIVE':'PAUSED')]])+`<div class="form-actions">${btn('切换租户','switch-tenant',t.id,'primary')}</div>`;break;}
case 'role-detail':{const r=C.requireOwned(state.roles,tenant(),id);if(!r)return;title='角色详情 · '+r.name;html=kvRows([['角色 ID',r.id],['数据范围',r.scope],['权限集合',r.permissions.map(esc).join('<br>')]])+'<div class="notice spaced">后端必须同时检查操作权限和目标资产的数据权限。</div>';break;}
case 'key-detail':{const k=C.requireOwned(state.apiKeys,tenant(),id);if(!k)return;title='API Key · '+k.name;html=kvRows([['所属项目',esc(k.project)],['密钥前缀',`<code>${esc(k.prefix)}</code>`],['Scope',esc(k.scope)],['状态',badge(k.status)],['累计调用',fmt(k.calls)]])+'<div class="notice spaced">已创建密钥的原始值无法再次查看；生产中只持有摘要。</div>';break;}
case 'manage-members':title='组织成员管理';html=table(['成员','组织','角色'],scoped(state.members).map(m=>[esc(m.name),esc(m.org),esc(m.roles.join(','))]));wide=true;break;
case 'configure-storage':title='多云对象存储 SPI';html='<div class="notice">建议以 S3 兼容驱动为核心，独立适配 OSS / COS / OBS。此处不保存真实对象存储密钥。</div>'+kvRows([['开发环境','MinIO'],['生产默认','S3 兼容'],['分片完成','CompleteMultipartUpload'],['私有下载','短期签名 URL'],['扫描','ClamAV 隔离区']]);break;
default:title='演示操作';html='<div class="notice">此操作展示产品需求与界面，不触发真实后端行为。</div>';
}modal={title,html,wide};drawer=null;renderOverlay();}
function renderOverlay(){const root=document.getElementById('overlay-root');if(!root)return;if(modal){root.innerHTML=`<div class="overlay" data-action="close-backdrop"><section class="modal ${modal.wide?'wide':''}" role="dialog" aria-modal="true" aria-labelledby="modal-title"><div class="modal-head"><h2 id="modal-title">${esc(modal.title)}</h2><button class="icon-button" aria-label="关闭对话框" data-action="close">×</button></div><div class="modal-body">${modal.html}</div></section></div>`;root.querySelector('input:not([type=hidden]),select,button')?.focus();}else if(drawer){root.innerHTML=`<div class="drawer-overlay" data-action="close-backdrop"><aside class="drawer" role="dialog" aria-modal="true" aria-label="${attr(drawer.title)}"><div class="drawer-head"><h2>${esc(drawer.title)}</h2><button class="icon-button" aria-label="关闭详情" data-action="close">×</button></div><div class="drawer-body">${drawer.html}</div></aside></div>`;root.querySelector('[data-action=close]')?.focus();}else root.innerHTML='';}
function closeOverlay(){modal=null;drawer=null;renderOverlay();}
function recordAudit(action,target='—',result='成功'){state.audit.unshift({id:C.uid('aud'),tenantId:tenant(),actor:'演示管理员',action,target,result,createdAt:C.now()});}
function notify(message,kind='ok'){const root=document.getElementById('toast-root');const el=document.createElement('div');el.className='toast '+kind;el.setAttribute('role',kind==='err'?'alert':'status');el.textContent=(kind==='ok'?'✔ ':'')+message;root.appendChild(el);setTimeout(()=>el.remove(),4300);}
function onAction(action,id,element){switch(action){
case 'menu':document.getElementById('app').classList.toggle('menu-open');break;
case 'close':closeOverlay();break;
case 'close-backdrop':if(element?.classList.contains('overlay')||element?.classList.contains('drawer-overlay'))closeOverlay();break;
case 'toggle-theme':settings.dark=!settings.dark;persistUI();render();break;
case 'go-assets':go('assets');break;case 'go-jobs':go('jobs');break;case 'go-runtimes':go('runtimes');break;case 'go-audit':go('audit');break;case 'go-usage':go('usage');break;
case 'open-upload':go('uploads');setTimeout(()=>document.getElementById('dropzone')?.focus(),0);break;
case 'asset-detail':openDrawer('asset',id);break;
case 'job-detail':openDrawer('job',id);break;
case 'worker-detail':openDrawer('worker',id);break;
case 'pipeline-detail':openDrawer('pipeline',id);break;
case 'folder-tab':filter=id==='collections'?'collections':'all';render();break;
case 'api-tab':filter=id==='reference'?'reference':'all';render();break;
case 'runtime-filter':filter=id;render();break;
case 'toggle-asset-view':view=view==='grid'?'table':'grid';render();break;
case 'new-job':case 'new-project':case 'new-schema':case 'new-folder':case 'new-collection':case 'new-key':case 'new-webhook':case 'new-event':case 'new-pipeline':case 'new-schedule':case 'new-tenant':case 'new-org':case 'new-role':case 'new-processor':case 'sign-link':case 'runtime-config':case 'show-upload-flow':case 'configure-storage':case 'manage-members':case 'plan-detail':showModal(action,id);break;
case 'processor-spec':case 'schema-detail':case 'edit-project':case 'versions-asset':case 'tenant-detail':case 'role-detail':case 'key-detail':case 'share-asset':case 'delete-asset':case 'edit-asset':case 'edit-org':case 'rename-item':showModal(action,id);break;
case 'approve-asset':case 'reject-asset':{const a=C.requireOwned(state.assets,tenant(),id);if(!a)return;a.reviewStatus=action==='approve-asset'?'APPROVED':'REJECTED';recordAudit(action==='approve-asset'?'审核通过':'审核驳回',a.id);persist();render();notify('演示审核状态已更新');break;}
case 'toggle-schema':{const s=C.requireOwned(state.metadataSchemas||[],tenant(),id);if(!s)return;s.status=s.status==='ACTIVE'?'PAUSED':'ACTIVE';recordAudit('元数据模板状态变更',s.id);persist();render();notify('模板状态已更新');break;}
case 'rollback-asset':{const a=C.requireOwned(state.assets,tenant(),id);if(!a)return;a.version++;recordAudit('资产版本回滚（模拟）',a.id);persist();closeOverlay();render();notify('已模拟基于历史版本创建新版本');break;}
case 'create-job-asset':closeOverlay();showModal('new-job');setTimeout(()=>{const select=document.querySelector('[name=assetId]');if(select)select.value=id;},0);break;
case 'confirm-delete':{const a=C.requireOwned(state.assets,tenant(),id);if(!a){notify('资产不存在或未授权','err');return;}state.assets=state.assets.filter(x=>x.id!==id);state.jobs=state.jobs.filter(x=>!(x.assetId===id&&x.tenantId===tenant()));recordAudit('删除资产',a.id);persist();closeOverlay();render();notify('演示资产已从当前租户移除');break;}
case 'retry-job':case 'cancel-job':case 'simulate-job-one':{const j=C.requireOwned(state.jobs,tenant(),id);if(!j){notify('当前租户无法操作此任务','err');break;}let to=action==='retry-job'?'QUEUED':action==='cancel-job'?'CANCELLED':j.status==='QUEUED'?'RUNNING':j.status==='RUNNING'?'SUCCEEDED':null;const next=C.transitionJob(j,to);if(!next.ok){notify('当前任务状态不允许此操作','warn');break;}Object.assign(j,next.job);recordAudit('任务状态变更',j.id);persist();closeOverlay();render();notify(`任务 ${j.id} 已切换至 ${statusText[j.status]}`);break;}
case 'simulate-jobs':{let done=0;for(const j of scoped(state.jobs)){const next=C.transitionJob(j,j.status==='QUEUED'?'RUNNING':j.status==='RUNNING'?'SUCCEEDED':null);if(next.ok){Object.assign(j,next.job);done++;}}if(done){recordAudit('模拟推进任务状态',`${done} 个任务`);persist();render();notify(`已推进 ${done} 个模拟任务`);}else notify('没有可以推进的任务','warn');break;}
case 'run-pipeline':{const p=C.requireOwned(state.pipelines,tenant(),id);if(!p||!p.enabled){notify('工作流不可执行','warn');return;}const a=scoped(state.assets)[0];if(!a){notify('当前租户暂无资产，请先上传文件','warn');return;}const j=C.createJob(tenant(),a.id,p.steps.join(' → '),state.assets);state.jobs.unshift(j);recordAudit('触发工作流',p.id);persist();go('jobs');notify('已创建一条模拟处理任务');break;}
case 'toggle-pipeline':{const p=C.requireOwned(state.pipelines,tenant(),id);if(!p)return;p.enabled=!p.enabled;recordAudit('工作流状态切换',p.id);persist();render();notify('工作流状态已更新');break;}
case 'toggle-worker':{const w=state.workers.find(x=>x.id===id);if(!w)return;w.status=w.status==='RUNNING'?'IDLE':'RUNNING';recordAudit('模拟执行器状态切换',w.id);persist();render();notify('Worker 模拟状态已更新（未操作实际容器）');break;}
case 'toggle-schedule':{const s=C.requireOwned(state.schedules,tenant(),id);if(!s)return;s.status=s.status==='ACTIVE'?'PAUSED':'ACTIVE';recordAudit('调度状态变更',s.id);persist();render();notify('调度任务状态已更新');break;}
case 'run-schedule':{const s=C.requireOwned(state.schedules,tenant(),id);if(!s)return;s.last='成功（模拟）';recordAudit('手动触发调度',s.id);persist();render();notify('模拟调度已触发，仅更新演示记录');break;}
case 'toggle-key':{const k=C.requireOwned(state.apiKeys,tenant(),id);if(!k)return;k.status=k.status==='ACTIVE'?'PAUSED':'ACTIVE';recordAudit('API Key 状态变更',k.id);persist();render();notify('API Key 状态已更新');break;}
case 'toggle-webhook':{const w=C.requireOwned(state.webhooks,tenant(),id);if(!w)return;w.status=w.status==='ACTIVE'?'PAUSED':'ACTIVE';recordAudit('Webhook 端点状态变更',w.id);persist();render();notify('Webhook 状态已更新');break;}
case 'test-webhook':{const w=C.requireOwned(state.webhooks,tenant(),id);if(!w)return;if(w.status!=='ACTIVE'){notify('端点已暂停，无法模拟投递','warn');return;}w.success++;recordAudit('模拟 Webhook 投递',w.id);persist();render();notify('模拟投递成功（没有发送真实网络请求）');break;}
case 'switch-tenant':if(!state.tenants.find(t=>t.id===id))return;settings.tenantId=id;persistUI();filter='all';query='';closeOverlay();render();notify('演示租户已切换，资源列表已隔离');break;
case 'toggle-setting':settings[id]=!!element.checked;persistUI();notify('原型策略开关已保存（不代表后端生效）');break;
case 'reset':showModal('confirm-reset');break;
case 'confirm-reset':state=C.createSeed();persist();settings.tenantId='t1';persistUI();uploadProgress=[];closeOverlay();go('overview');notify('演示数据已重置');break;
case 'export':case 'export-audit':{const data=action==='export-audit'?scoped(state.audit):{tenantId:tenant(),assets:scoped(state.assets),jobs:scoped(state.jobs),projects:scoped(state.projects),webhooks:scoped(state.webhooks)};downloadJSON(data,action==='export-audit'?'audit':'peach-media-demo');notify('演示数据已导出为 JSON');break;}
case 'copy-api':copyText('POST /openapi/v1/uploads\nAuthorization: Bearer <api-key>\nIdempotency-Key: request-001');break;
case 'copy-delivery':copyText(`https://media.example.com/t/${tenant()}/asset_001/w_800,h_800,c_cover,f_webp,q_80`);break;
case 'purge-cache':recordAudit('模拟清理 CDN 缓存');persist();notify('已记录模拟缓存刷新事件（没有调用 CDN）');break;
case 'inject-mq':case 'inject-worker':case 'inject-retry':recordAudit('模拟故障注入',action);persist();render();notify('已生成演示故障与审计记录');break;
default:notify(`操作 ${action} 尚未绑定`, 'warn');}
}
function downloadJSON(value,name){const blob=new Blob([JSON.stringify(value,null,2)],{type:'application/json;charset=utf-8'});const href=URL.createObjectURL(blob);const a=document.createElement('a');a.href=href;a.download=`${name}-${tenant()}.json`;a.click();setTimeout(()=>URL.revokeObjectURL(href),2000);}
async function copyText(str){try{await navigator.clipboard.writeText(str);notify('文本已复制到剪贴板');}catch{modal={title:'复制文本',html:`<label class="form-field">选择并复制<textarea rows="5" readonly>${esc(str)}</textarea></label>`};renderOverlay();notify('浏览器限制自动复制，请手动复制','warn');}}
function onSubmit(formEl){const fd=new FormData(formEl),get=n=>String(fd.get(n)||'').trim();const kind=formEl.dataset.form;const first=formEl.querySelector('input:invalid,textarea:invalid,select:invalid');if(first){first.focus();notify('请先填写必填字段并检查格式','err');return;}const name=get('name');if(['new-project','new-schema','new-folder','new-collection','new-pipeline','new-schedule','new-tenant','new-org','new-role','new-key','new-webhook'].includes(kind)&&!name){notify('名称不能为空','err');formEl.querySelector('[name=name]')?.focus();return;}try{switch(kind){
case 'new-project':{if(scoped(state.projects).some(p=>p.name===name))throw new Error('项目名称已存在');state.projects.push({id:C.uid('pr'),tenantId:tenant(),name,env:get('env'),assets:0});recordAudit('创建项目',name);break;}
case 'edit-project':{const p=C.requireOwned(state.projects,tenant(),get('id'));if(!p)throw new Error('项目不存在');p.name=name;p.env=get('env');recordAudit('编辑项目',p.id);break;}
case 'new-schema':{const fields=get('fields').split(/[,，]/).map(x=>x.trim()).filter(Boolean);if(!fields.length)throw new Error('必须至少包含一个字段');if(!Array.isArray(state.metadataSchemas))state.metadataSchemas=[];state.metadataSchemas.push({id:C.uid('schema'),tenantId:tenant(),name,fields:fields.join(','),status:'ACTIVE'});recordAudit('创建 Schema',name);break;}
case 'new-job':{const j=C.createJob(tenant(),get('assetId'),get('type'),state.assets);j.runtime=get('runtime');state.jobs.unshift(j);recordAudit('创建媒体处理任务',j.id);break;}
case 'new-folder':state.folders.unshift({id:C.uid('f'),tenantId:tenant(),name,path:`/${name}`,assets:0});recordAudit('新增目录',name);break;
case 'new-collection':state.collections.unshift({id:C.uid('col'),tenantId:tenant(),name,count:0});recordAudit('新增集合',name);break;
case 'rename-item':{const item=[...state.folders,...state.collections].find(x=>x.id===get('id')&&x.tenantId===tenant());if(!item)throw new Error('找不到该目录或集合');item.name=name;recordAudit('重命名目录或集合',item.id);break;}
case 'edit-asset':{const a=C.requireOwned(state.assets,tenant(),get('id'));if(!a)throw new Error('没有该资产的编辑权限');a.name=name;a.tag=get('tag');a.version++;recordAudit('修改资产元数据',a.id);break;}
case 'new-key':{const raw=`pm_demo_${C.uid('secret')}`;const k={id:C.uid('key'),tenantId:tenant(),name,project:get('project'),prefix:`${raw.slice(0,15)}…`,scope:get('scope'),status:'ACTIVE',calls:0,createdAt:C.now().slice(0,10)};state.apiKeys.unshift(k);recordAudit('创建 API Key',k.id);persist();modal={title:'一次性演示密钥（仅当前会话显示）',html:`<div class="notice">以下是无实际授权能力的演示密钥，原型不会保存完整值。正式系统必须只存储密钥摘要。</div><pre class="code-sample spaced">${esc(raw)}</pre><div class="form-actions">${btn('复制密钥','copy-once',raw,'primary')}${btn('已保存','close')}</div>`};render();notify('演示 API Key 已创建');return;}
case 'new-webhook':{const url=get('url');const valid=C.safeHref(url);if(!valid||!valid.startsWith('https://'))throw new Error('回调地址必须是有效 HTTPS URL');state.webhooks.unshift({id:C.uid('wh'),tenantId:tenant(),name,url:valid,events:get('events'),status:'ACTIVE',success:0,failed:0});recordAudit('新增 Webhook',name);break;}
case 'new-event':{const eid=C.uid('evt');state.events.unshift({id:eid,tenantId:tenant(),type:get('type'),resource:get('resource'),status:'ACCEPTED',createdAt:C.now()});recordAudit('模拟事件上报',eid);break;}
case 'new-pipeline':{const steps=get('steps').split(/[,，]/).map(s=>s.trim()).filter(Boolean);if(!steps.length||steps.length>12)throw new Error('请输入 1–12 个处理步骤');state.pipelines.unshift({id:C.uid('pipe'),tenantId:tenant(),name,steps,trigger:get('trigger'),enabled:true});recordAudit('新增处理流水线',name);break;}
case 'new-schedule':state.schedules.unshift({id:C.uid('sch'),tenantId:tenant(),name,cron:get('cron'),next:'模拟计划',status:'ACTIVE',last:'尚未运行'});recordAudit('创建调度任务',name);break;
case 'new-tenant':{const code=get('code');if(!/^[A-Za-z][A-Za-z0-9_-]{2,31}$/.test(code))throw new Error('编码必须为 3–32 位，以字母开头');if(state.tenants.some(x=>x.code===code))throw new Error('租户编码已存在');const t={id:C.uid('t'),name,code,plan:get('plan'),active:true,users:1};state.tenants.push(t);recordAudit('创建租户',t.id);break;}
case 'new-org':{const parentId=get('parentId')||null;if(parentId&&!C.requireOwned(state.orgs,tenant(),parentId))throw new Error('上级组织必须属于当前租户');state.orgs.push({id:C.uid('o'),tenantId:tenant(),name,type:get('type'),parentId});recordAudit('新建组织单元',name);break;}
case 'edit-org':{const o=C.requireOwned(state.orgs,tenant(),get('id'));if(!o)throw new Error('组织不存在');o.name=name;o.type=get('type');recordAudit('修改组织单元',o.id);break;}
case 'new-role':state.roles.push({id:C.uid('r'),tenantId:tenant(),name,scope:get('scope'),permissions:get('permissions').split(/[,，]/).map(x=>x.trim()).filter(Boolean)});recordAudit('新增角色',name);break;
case 'sign-link':{const asset=C.requireOwned(state.assets,tenant(),get('assetId'));if(!asset)throw new Error('只能分享当前租户的资源');const duration=get('duration');const fakeUrl=`https://media.example.com/demo/${tenant()}/${asset.id}?expires=${duration}&signature=DEMO_NOT_VALID`;modal={title:'模拟媒体签名链接',html:`<p class="small muted">该链接仅展示签名交付形式，不可用于真实下载。</p><pre class="code-sample">${esc(fakeUrl)}</pre><div class="form-actions">${btn('复制示例链接','copy-once',fakeUrl,'primary')}${btn('关闭','close')}</div>`};renderOverlay();recordAudit('生成模拟分享链接',asset.id);persist();return;}
case 'new-processor':{if(!Array.isArray(state.extraProcessors))state.extraProcessors=[];state.extraProcessors.push({id:C.uid('proc'),tenantId:tenant(),code:get('code'),image:get('image'),mode:get('mode')});recordAudit('提交处理器注册方案',get('code'));notify('处理器已添加到演示列表；未实际启动容器');break;}
default:throw new Error('未知表单类型');}
recordAudit('原型表单操作',kind);persist();closeOverlay();render();notify('演示数据已更新');}catch(e){notify(e.message||'提交失败','err');}}
function uploadFiles(files){if(!files?.length)return;const project=document.getElementById('upload-project')?.value||'默认项目';for(const file of Array.from(files).slice(0,15)){if(!file.name||file.size<0)continue;const ext=file.name.split('.').pop().toLowerCase();const type=/^(png|jpg|jpeg|gif|webp|avif|svg)$/.test(ext)?'image':/^(mp4|mov|mkv|webm)$/.test(ext)?'video':/^(mp3|wav|aac|flac)$/.test(ext)?'audio':/^(pdf|docx|doc|ppt|pptx|xlsx|txt)$/.test(ext)?'document':/^(csv|json|parquet)$/.test(ext)?'dataset':'archive';const asset=C.createAsset({name:file.name,size:file.size,type,project},tenant());state.assets.unshift(asset);const prog={id:asset.id,name:file.name,size:file.size,progress:0,status:'UPLOADING'};uploadProgress.unshift(prog);let step=0;const interval=setInterval(()=>{step++;prog.progress=Math.min(100,step*25);const slot=document.getElementById('upload-progress');if(slot)slot.innerHTML=uploadProgressMarkup();if(prog.progress===100){clearInterval(interval);prog.status='DONE';asset.status='READY';const j=C.createJob(asset.tenantId,asset.id,type==='video'?'VIDEO_TRANSCODE':type==='image'?'IMAGE_RESIZE':'METADATA_EXTRACT',state.assets);state.jobs.unshift(j);recordAudit('演示上传完成',asset.id);persist();notify(`${file.name} 上传模拟完成；已生成处理任务`);if(route==='uploads')render();}},450);intervals.push(interval);}persist();const target=document.getElementById('upload-progress');if(target)target.innerHTML=uploadProgressMarkup();notify(`已开始 ${Math.min(files.length,15)} 个文件的模拟上传`);}
function bind(){document.addEventListener('click',e=>{const nav=e.target.closest('[data-route]');if(nav){e.preventDefault();go(nav.dataset.route);return;}const action=e.target.closest('[data-action]');if(action){if(action.dataset.action==='toggle-setting')return;if(action.dataset.action==='close-backdrop'&&e.target!==action)return;if(action.dataset.action==='copy-once'){copyText(action.dataset.id||'');return;}onAction(action.dataset.action,action.dataset.id||'',action);return;}const drop=e.target.closest('#dropzone');if(drop&&!e.target.matches('input'))document.getElementById('native-file')?.click();});document.addEventListener('submit',e=>{const form=e.target.closest('[data-form]');if(form){e.preventDefault();onSubmit(form);}});document.addEventListener('change',e=>{if(e.target.id==='tenant-selector'){settings.tenantId=e.target.value;persistUI();filter='all';query='';render();notify('已切换当前租户');}if(e.target.id==='asset-type'||e.target.id==='status-filter'){filter=e.target.value;render();}if(e.target.id==='native-file')uploadFiles(e.target.files);if(e.target.classList.contains('toggle')&&e.target.dataset.action==='toggle-setting'){onAction('toggle-setting',e.target.dataset.id,e.target);}});document.addEventListener('input',e=>{if(e.target.id==='list-search'){const start=e.target.selectionStart??0;query=e.target.value;render();const box=document.getElementById('list-search');box?.focus();try{box?.setSelectionRange(start,start);}catch{}}});document.addEventListener('keydown',e=>{if(e.key==='Enter'&&e.target.id==='global-search'){const term=e.target.value.trim().toLowerCase();if(!term)return;const match=Object.entries(PAGE_META).find(([key,v])=>`${v[0]} ${v[1]} ${v[2]} ${key}`.toLowerCase().includes(term));if(match){go(match[0]);notify(`已定位至 ${match[1][0]}`);}else notify('没有找到对应功能页面','warn');}if((e.key==='Enter'||e.key===' ')&&e.target.closest('[role=button][data-action]')){e.preventDefault();e.target.click();}if((e.key==='Enter'||e.key===' ')&&e.target.id==='dropzone'){e.preventDefault();document.getElementById('native-file')?.click();}});document.addEventListener('dragover',e=>{if(e.target.closest('#dropzone')){e.preventDefault();document.getElementById('dropzone')?.classList.add('drag');}});document.addEventListener('dragleave',e=>{if(e.target.closest('#dropzone'))document.getElementById('dropzone')?.classList.remove('drag');});document.addEventListener('drop',e=>{if(e.target.closest('#dropzone')){e.preventDefault();document.getElementById('dropzone')?.classList.remove('drag');uploadFiles(e.dataTransfer?.files);}});}
// One-shot non-persistent secret and reset dialogs are special actions.
const originalShowModal=showModal;showModal=function(kind,id=''){if(kind==='confirm-reset'){modal={title:'重置全部演示数据',html:`<div class="notice">此操作会清空当前浏览器中 Peach Media 的模拟记录，恢复全部预览数据，但不会修改任何远程资源。</div><div class="form-actions">${btn('取消','close')}${btn('确认重置','confirm-reset','','danger')}</div>`};drawer=null;renderOverlay();return;}originalShowModal(kind,id);};
if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',init);else init();
})();
